from .base_wrapper import ListAbstractionsWrapper
from taf.config.testline.gnb.gnb import CloudBts


class _ControlWrapper(ListAbstractionsWrapper):
    """
    All redirections for control are contained inside this wrapper's properties
    """
    def __init__(self, tl_config):
        super(_ControlWrapper, self).__init__(tl_config)
        self._os_auth_url = 'http://169.254.12.2:5000/v3'

    def _get_cloud_hosting(self):
        return self.tl_config.cloud_hostings[0]

    def _get_cloud_hosting_from_cloudbts(self):
        cloudbts = self.get_instance(CloudBts, self.tl_config.gnbs)
        return cloudbts.cloud_deployment.cloud_hosting

    def _get_control_node(self):
        try:
            control = self._get_cloud_hosting_from_cloudbts().control_nodes[0]
        except AttributeError:
            control = self._get_cloud_hosting().control_nodes[0]
        return control

    @property
    def addr(self):
        return self._get_control_node().open_stack_connection_details.ip_addr

    @property
    def username(self):
        return self._get_control_node().default_ssh_connection_details.username

    @property
    def password(self):
        return self._get_control_node().default_ssh_connection_details.password

    @property
    def os_tenant_name(self):
        return self._get_control_node().open_stack_connection_details.tenant

    @property
    def os_password(self):
        return self._get_control_node().open_stack_connection_details.password

    @property
    def os_username(self):
        return self._get_control_node().open_stack_connection_details.username

    @property
    def os_auth_url(self):
        return self._os_auth_url

    @os_auth_url.setter
    def os_auth_url(self, value):
        self._os_auth_url = value
